'use strict';
const assert=require('node:assert/strict'),{create}=require('../demo-core'),F=require('../fixtures'),config=require('../br03-demo-snapshots'),{create:unitPolicy}=require('../br03-policy'),{create:presentation}=require('../presentation-policy');
let groups=0;
const check=(name,fn)=>{fn();groups++;console.log('PASS '+name);};
function fresh(verified=false){const core=create();core.setScenario('normal');if(verified){core.requestPhone();core.resolvePhone('success');}const units=unitPolicy({core,fixture:F,config});return {core,units,p:presentation({core,fixture:F,unitPolicy:units})};}
check('public reference never issues a formal term amount',()=>{const {core,p}=fresh();const v=p.price(['SIM_BJ01_U03']);assert.equal(v.kind,'reference');assert.equal(v.value,F.units.find(x=>x.id==='SIM_BJ01_U03').base_month);assert.equal(v.amounts,null);assert.equal(core.state().quote,null);});
check('verified lease uses the same rent, average and payable engine',()=>{const {core,p}=fresh(true);const ids=['SIM_BJ02_U04'],v=p.price(ids),a=core.formalAmounts(ids,6);assert.equal(v.kind,'term');assert.equal(v.value,a.rent_total);assert.deepEqual(v.amounts,a);assert(v.average.includes(String(a.monthly_average)));});
check('verification without explicit lease still shows monthly reference',()=>{const {core,p}=fresh(true);core.setRequirement(3.5,null,false);assert.equal(p.price(['SIM_BJ01_U03']).kind,'reference');assert.equal(core.state().requirement.term_months,null);});
check('revoking verification immediately removes term price context',()=>{const {core,p}=fresh(true);assert.equal(p.price(['SIM_BJ01_U04']).kind,'term');core.revokePhone();assert.equal(p.price(['SIM_BJ01_U04']).kind,'reference');assert.equal(p.facts(['SIM_BJ01_U04']).promoLabel,'');});
check('same unit activity facts are shared with BR03 without another engine',()=>{const {p,units}=fresh(true);for(const id of ['SIM_BJ01_U03','SIM_BJ01_U04','SIM_BJ02_U03','SIM_BJ02_U04'])assert.deepEqual(p.facts([id]),units.facts(F.units.find(u=>u.id===id)));});
check('price change invalidates the qualified special-unit badge',()=>{const {core,p}=fresh(true);const state=core.state();state.prices.SIM_BJ01_U04=999;const next=create({state}),q=presentation({core:next,fixture:F,unitPolicy:unitPolicy({core:next,fixture:F,config})});assert.equal(q.facts(['SIM_BJ01_U04']).promoLabel,'');assert.equal(q.price(['SIM_BJ01_U04']).value,next.formalAmounts(['SIM_BJ01_U04'],6).rent_total);});
check('unavailable unit has no urgency fact',()=>{const {core,p}=fresh(true);core.markUnavailable('SIM_BJ02_U04');assert.equal(p.facts(['SIM_BJ02_U04']).state,'UNAVAILABLE');assert.equal(p.facts(['SIM_BJ02_U04']).inventoryLine,'');});
check('combination rent is one calculation with no invented combined activity',()=>{const {core,p}=fresh(true);const ids=['SIM_BJ01_U03','SIM_BJ01_U04'];assert.equal(p.price(ids).value,core.formalAmounts(ids,6).rent_total);assert.equal(p.facts(ids).promoLabel,'');assert.equal(p.facts(ids).inventoryLine,'');});
check('store facilities never turn old operating tags into price claims',()=>{const {p}=fresh();for(const s of F.stores){const rows=p.services(s);assert(rows.every(x=>s.serviceTags.includes(x)));assert(!rows.includes('双11大促'));assert(rows.length<=2);}});
check('home cubic references remain public and retain their published number',()=>{const {p,core}=fresh();for(const s of F.stores.filter(s=>s.teaserCubicPrice)){const v=p.cubicReference(s);assert(v);assert.equal(Number(v.money.replace(/[¥,]/g,'')),s.teaserCubicPrice);assert.equal(v.unit,'/m³/月起');}assert(!core.authorized());assert.equal(p.cubicReference({}),null);});
check('unknown or repeated price IDs cannot silently become a zero price',()=>{const {p}=fresh();assert.throws(()=>p.price(['missing']),/UNKNOWN_PRESENTATION_UNIT/);assert.throws(()=>p.price([]),/INVALID_PRESENTATION_IDS/);assert.throws(()=>p.price(['SIM_BJ01_U03','SIM_BJ01_U03']),/INVALID_PRESENTATION_IDS/);});
check('formatting does not mutate the persisted demand, selection or quote',()=>{const {core,p}=fresh(true),before=JSON.stringify(core.state());p.price(['SIM_BJ01_U03']);p.services(F.stores[0]);p.facts(['SIM_BJ01_U03']);assert.equal(JSON.stringify(core.state()),before);});
console.log(JSON.stringify({groups,result:'PASS'}));
